//! `pack`: the real binary, end to end. Keys are generated by the binary at test time; every
//! command's output is scanned for every secret generated so far. The release a run writes is read
//! back the way a client reads it: `keys.json` under the config's root, a feed signed in-test that
//! points at the manifest, then `verify_manifest`, the pack's hash and `decode_verified` on every
//! frame, whose output must equal the input file.
//!
//! Each run gets its own temp dir (`TMPDIR`, `TMP`, `TEMP`), so the work-dir count of one test is
//! not disturbed by another running in parallel.

mod common;

use std::cell::RefCell;
use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Output;

use common::*;
use ed25519_dalek::SigningKey;
use ed25519_dalek::pkcs8::DecodePrivateKey;
use lunepack_codec_lzma::LzmaCodec;
use lunepack_core::digest::U53;
use lunepack_core::{
    AppId, ArtifactRef, Channel, Clock, ClockReading, CodecId, Hasher, PayloadKind, ReleaseDoc,
    RollbackFloor, Signer, Target, TrustedRoot, VerifiedEntry, VerifiedKeySet, VerifiedManifest,
    decode_verified, next_feed, sign_envelope, verify_feed, verify_key_set, verify_manifest,
};
use lunepack_crypto::{Ed25519Signer, Ed25519Verifier, Sha256Hasher};
use lunepack_testkit::exe_headers;

const APP: &str = "org.example.hello";
const T0: u64 = 1_800_000_000;
const DAY: u64 = 86_400;
const WORK_PREFIX: &str = "lunepack-pack-";

struct At(u64);

impl Clock for At {
    fn now_unix_secs(&self) -> u64 {
        self.0
    }
}

struct Key {
    path: PathBuf,
    public: String,
}

fn s(path: &Path) -> &str {
    path.to_str().expect("utf-8 path")
}

fn hex(text: &str) -> [u8; 32] {
    let bytes: Vec<u8> = (0..32)
        .map(|i| u8::from_str_radix(&text[2 * i..2 * i + 2], 16).unwrap())
        .collect();
    bytes.try_into().unwrap()
}

fn spec(k: &Key) -> String {
    format!("file:{}", s(&k.path))
}

/// A config with one root key, and release dirs whose `keys.json` lists `release` keys.
struct World {
    dir: tempfile::TempDir,
    config: PathBuf,
    tmp: PathBuf,
    root: Key,
    release: Vec<Key>,
    threshold: u64,
    secrets: RefCell<Vec<Vec<u8>>>,
}

/// One `pack` invocation.
struct Pack<'a> {
    input: &'a Path,
    version: &'a str,
    target: &'a str,
    release_dir: &'a Path,
    signers: Vec<String>,
    epoch: u64,
    extra: Vec<&'a str>,
}

impl World {
    /// `release_keys` keys, `threshold` of them needed; `keys_extra` goes to `keys set`.
    fn new(release_keys: usize, threshold: u64) -> World {
        let dir = tempfile::tempdir().unwrap();
        let tmp = dir.path().join("tmp");
        fs::create_dir(&tmp).unwrap();
        let mut w = World {
            config: dir.path().join("lunepack.toml"),
            tmp,
            root: Key {
                path: PathBuf::new(),
                public: String::new(),
            },
            release: Vec::new(),
            threshold,
            secrets: RefCell::new(Vec::new()),
            dir,
        };
        w.root = w.new_key("root");
        w.release = (0..release_keys)
            .map(|i| w.new_key(&format!("release{i}")))
            .collect();
        let out = w.run(
            &["init", "--app-id", APP, "--root-key", &w.root.public],
            &[],
        );
        assert_ok(&out, "init");
        w
    }

    fn cmd(&self, args: &[&str], env: &[(&str, &str)]) -> Output {
        let output = run(args, env);
        let secrets = self.secrets.borrow();
        let refs: Vec<&[u8]> = secrets.iter().map(Vec::as_slice).collect();
        assert_no_secrets(&output, &refs);
        output
    }

    fn run(&self, args: &[&str], env: &[(&str, &str)]) -> Output {
        let mut full = vec!["--config", s(&self.config)];
        full.extend_from_slice(args);
        self.cmd(&full, env)
    }

    fn new_key(&self, name: &str) -> Key {
        let base = self.dir.path().join(name);
        let out = self.cmd(&["keys", "gen", s(&base)], &[]);
        assert_ok(&out, "keys gen");
        let path = base.with_extension("key");
        let pem = fs::read_to_string(&path).unwrap();
        let seed = SigningKey::from_pkcs8_pem(&pem).unwrap().to_bytes();
        let mut secrets = self.secrets.borrow_mut();
        secrets.push(pem.into_bytes());
        secrets.push(seed.to_vec());
        Key {
            path,
            public: field(&stdout(&out), "public:"),
        }
    }

    /// A release dir named `name` with `keys.json` written at `T0`. Each release dir has its own
    /// publisher state file (a copy of the config in `<name>.publisher/`): one state file records
    /// one release dir, and a second dir without the recorded `keys.json` is refused.
    fn release_dir(&self, name: &str, keys_extra: &[&str]) -> PathBuf {
        let dir = self.dir.path().join(name);
        fs::create_dir(&dir).unwrap();
        let publisher = self.dir.path().join(format!("{name}.publisher"));
        fs::create_dir(&publisher).unwrap();
        let config = publisher.join("lunepack.toml");
        fs::copy(&self.config, &config).unwrap();
        let t = self.threshold.to_string();
        let mut args = vec![
            "--config",
            s(&config),
            "keys",
            "set",
            "--release-dir",
            s(&dir),
            "--threshold",
            &t,
        ];
        for k in &self.release {
            args.extend_from_slice(&["--release-key", &k.public]);
        }
        let root = spec(&self.root);
        args.extend_from_slice(&["--sign", &root]);
        args.extend_from_slice(keys_extra);
        let out = self.cmd(&args, &[("SOURCE_DATE_EPOCH", &T0.to_string())]);
        assert_ok(&out, "keys set");
        dir
    }

    fn all_signers(&self) -> Vec<String> {
        self.release.iter().map(spec).collect()
    }

    fn pack(&self, p: &Pack<'_>) -> Output {
        self.pack_with_tmp(p, &self.tmp)
    }

    fn pack_with_tmp(&self, p: &Pack<'_>, tmp: &Path) -> Output {
        let mut args = vec![
            "pack",
            "--input",
            s(p.input),
            "--version",
            p.version,
            "--target",
            p.target,
            "--release-dir",
            s(p.release_dir),
        ];
        for signer in &p.signers {
            args.extend_from_slice(&["--sign", signer]);
        }
        args.extend_from_slice(&p.extra);
        let epoch = p.epoch.to_string();
        let tmp = s(tmp);
        self.run(
            &args,
            &[
                ("SOURCE_DATE_EPOCH", &epoch),
                ("TMPDIR", tmp),
                ("TMP", tmp),
                ("TEMP", tmp),
            ],
        )
    }

    /// Appends `text` to the config (the `[update]` and `[install]` tables). Every user is a
    /// unix-only test.
    #[cfg(unix)]
    fn append_config(&self, text: &str) {
        use std::io::Write as _;
        let mut file = fs::OpenOptions::new()
            .append(true)
            .open(&self.config)
            .unwrap();
        file.write_all(text.as_bytes()).unwrap();
    }

    fn work_dirs(&self) -> usize {
        fs::read_dir(&self.tmp)
            .unwrap()
            .filter(|e| {
                e.as_ref()
                    .unwrap()
                    .file_name()
                    .to_string_lossy()
                    .starts_with(WORK_PREFIX)
            })
            .count()
    }

    fn keys(&self, release_dir: &Path) -> VerifiedKeySet {
        let root = TrustedRoot::from_parts(
            AppId::parse(APP).unwrap(),
            1,
            1,
            &[hex(&self.root.public)],
            &Sha256Hasher,
            &Ed25519Verifier,
        )
        .unwrap();
        verify_key_set(
            &root,
            &fs::read(release_dir.join("keys.json")).unwrap(),
            &RollbackFloor::default(),
            &ClockReading::read(&At(T0), None),
            &Sha256Hasher,
            &Ed25519Verifier,
        )
        .expect("keys.json verifies")
    }

    /// Reads a release the way a client does and returns the manifest and every decoded file.
    fn verify(
        &self,
        release_dir: &Path,
        version: &str,
        target: Target,
    ) -> (VerifiedManifest, BTreeMap<String, Vec<u8>>) {
        let keys = self.keys(release_dir);
        let base = release_dir.join(version);
        let manifest = fs::read(base.join(format!("{}.manifest.json", target.as_str()))).unwrap();
        let pack = fs::read(base.join(format!("{}.pack", target.as_str()))).unwrap();
        let app = AppId::parse(APP).unwrap();
        let channel = Channel::parse("stable").unwrap();
        let release = ReleaseDoc {
            version: version.to_owned(),
            targets: BTreeMap::from([(
                target.as_str().to_owned(),
                ArtifactRef {
                    path: format!("{version}/{}.manifest.json", target.as_str()),
                    size: U53::new(manifest.len() as u64).unwrap(),
                    sha256: Sha256Hasher.sha256(&manifest),
                },
            )]),
            rollout: None,
        };
        let feed = next_feed(None, &app, &channel, T0, vec![release], None).unwrap();
        let signers: Vec<Ed25519Signer> = self
            .release
            .iter()
            .map(|k| Ed25519Signer::from_key_file(&k.path).unwrap())
            .collect();
        let refs: Vec<&dyn Signer> = signers.iter().map(|s| s as &dyn Signer).collect();
        let feed_bytes = sign_envelope(
            PayloadKind::Feed,
            &feed.to_payload(),
            &refs,
            &Sha256Hasher,
            &Ed25519Verifier,
        )
        .unwrap();
        let feed = verify_feed(
            &keys,
            &feed_bytes,
            &app,
            &channel,
            &RollbackFloor::default(),
            &ClockReading::read(&At(T0), None),
            &Ed25519Verifier,
        )
        .unwrap();
        let entry = feed.target_entry(0, target).unwrap();
        let verified = verify_manifest(&keys, &entry, &manifest, &Sha256Hasher, &Ed25519Verifier)
            .expect("the manifest verifies");
        verified.pack().check_bytes(&pack, &Sha256Hasher).unwrap();
        let mut files = BTreeMap::new();
        for e in verified.entries() {
            if let VerifiedEntry::File { path, frame, .. } = e {
                let mut out = Vec::new();
                if let Some(f) = frame {
                    let start = f.offset() as usize;
                    let bytes = &pack[start..start + f.length() as usize];
                    decode_verified(f, bytes, &Sha256Hasher, &LzmaCodec, &mut out)
                        .expect("the frame decodes");
                }
                files.insert(path.as_str().to_owned(), out);
            }
        }
        (verified, files)
    }
}

fn file_entry<'a>(m: &'a VerifiedManifest, path: &str) -> &'a VerifiedEntry {
    m.entries()
        .iter()
        .find(|e| e.path().as_str() == path)
        .unwrap_or_else(|| panic!("no entry {path}"))
}

fn codec_of(m: &VerifiedManifest, path: &str) -> Option<CodecId> {
    match file_entry(m, path) {
        VerifiedEntry::File { frame, .. } => frame.as_ref().map(|f| f.codec()),
        _ => panic!("{path} is not a file"),
    }
}

#[cfg(unix)]
fn exec_of(m: &VerifiedManifest, path: &str) -> bool {
    match file_entry(m, path) {
        VerifiedEntry::File { exec, .. } => *exec,
        _ => panic!("{path} is not a file"),
    }
}

/// Deterministic noise (xorshift64), incompressible.
fn noise(seed: u64, len: usize) -> Vec<u8> {
    let mut x = seed | 1;
    (0..len)
        .map(|_| {
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            (x >> 24) as u8
        })
        .collect()
}

fn text(len: usize) -> Vec<u8> {
    b"The quick brown fox jumps over the lazy dog; pack me small.\n"
        .iter()
        .copied()
        .cycle()
        .take(len)
        .collect()
}

fn png(len: usize) -> Vec<u8> {
    let mut v = vec![0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A];
    v.extend(noise(7, len));
    v
}

fn write(root: &Path, rel: &str, bytes: &[u8]) {
    let path = root.join(rel);
    fs::create_dir_all(path.parent().unwrap()).unwrap();
    fs::write(path, bytes).unwrap();
}

#[cfg(unix)]
fn set_mode(path: &Path, mode: u32) {
    use std::os::unix::fs::PermissionsExt;
    fs::set_permissions(path, fs::Permissions::from_mode(mode)).unwrap();
}

/// The host's own target, where symlinks and exec bits exist on Unix.
fn host_target() -> &'static str {
    if cfg!(windows) {
        "windows-x86_64"
    } else {
        "linux-x86_64"
    }
}

/// Test 2's tree: nested dirs, an empty dir, an empty file, two identical files, a PNG, this test
/// binary, a text file; on Unix an exec bit and a symlink.
fn mixed_tree(root: &Path) {
    write(root, "docs/guide/intro.txt", &text(20_000));
    write(root, "docs/guide/copy-a.txt", &text(9_000));
    write(root, "shared/copy-b.txt", &text(9_000));
    write(root, "empty.dat", b"");
    write(root, "assets/logo.png", &png(4_000));
    fs::create_dir_all(root.join("empty-dir")).unwrap();
    let exe = std::env::current_exe().expect("current_exe");
    fs::create_dir_all(root.join("bin")).unwrap();
    fs::copy(&exe, root.join("bin/app")).unwrap();
    write(root, "bin/run.sh", b"#!/bin/sh\nexec ./app \"$@\"\n");
    #[cfg(unix)]
    {
        set_mode(&root.join("bin/run.sh"), 0o755);
        set_mode(&root.join("docs/guide/intro.txt"), 0o644);
        std::os::unix::fs::symlink("docs/guide/intro.txt", root.join("readme")).unwrap();
    }
}

fn read_input(root: &Path, rel: &str) -> Vec<u8> {
    fs::read(root.join(rel)).unwrap()
}

#[test]
fn the_secret_scan_fires_on_every_form() {
    self_check_secret_scan();
}

/// Tests 1, 2 and 4: one input packed with one worker and with four (the second with a 1 MiB
/// budget, so every job is admitted alone) gives byte-identical packs and manifests; the manifest
/// holds what the tree holds; no work dir is left behind.
#[test]
fn pack_is_deterministic_and_complete() {
    let w = World::new(1, 1);
    let input = tempfile::tempdir().unwrap();
    mixed_tree(input.path());
    let (a, b) = (w.release_dir("a", &[]), w.release_dir("b", &[]));
    assert_eq!(w.work_dirs(), 0);

    let target = host_target();
    let first = w.pack(&Pack {
        input: input.path(),
        version: "1.2.3",
        target,
        release_dir: &a,
        signers: w.all_signers(),
        epoch: T0,
        extra: vec!["--jobs", "1"],
    });
    assert_ok(&first, "pack --jobs 1");
    let out = stdout(&first);
    for stage in [
        "assemble:",
        "code-sign:",
        "hash:",
        "pack:",
        "sign:",
        "verify:",
        "placed:",
        "totals:",
    ] {
        assert!(out.contains(stage), "no {stage} line in {out:?}");
    }
    assert_eq!(w.work_dirs(), 0, "the work dir is removed after success");

    let second = w.pack(&Pack {
        input: input.path(),
        version: "1.2.3",
        target,
        release_dir: &b,
        signers: w.all_signers(),
        epoch: T0,
        extra: vec!["--jobs", "4", "--memory-budget-mib", "1"],
    });
    assert_ok(&second, "pack --jobs 4 --memory-budget-mib 1");
    // And truly in parallel: four workers under the default budget.
    let c = w.release_dir("c", &[]);
    let third = w.pack(&Pack {
        input: input.path(),
        version: "1.2.3",
        target,
        release_dir: &c,
        signers: w.all_signers(),
        epoch: T0,
        extra: vec!["--jobs", "4"],
    });
    assert_ok(&third, "pack --jobs 4");
    for name in [
        format!("1.2.3/{target}.pack"),
        format!("1.2.3/{target}.manifest.json"),
    ] {
        let first = fs::read(a.join(&name)).unwrap();
        for other in [&b, &c] {
            assert_eq!(
                first,
                fs::read(other.join(&name)).unwrap(),
                "{name} differs from the --jobs 1 run"
            );
        }
    }

    let target = Target::parse(target).unwrap();
    let (m, files) = w.verify(&a, "1.2.3", target);
    assert_eq!(m.issued(), T0);
    // Every file decodes to the input's bytes.
    for (path, bytes) in &files {
        assert_eq!(bytes, &read_input(input.path(), path), "{path}");
    }
    assert!(files.contains_key("empty.dat"));
    assert_eq!(codec_of(&m, "empty.dat"), None);
    assert_eq!(codec_of(&m, "assets/logo.png"), Some(CodecId::Stored));
    assert_eq!(codec_of(&m, "docs/guide/intro.txt"), Some(CodecId::Lzma2));
    assert!(
        matches!(
            codec_of(&m, "bin/app"),
            Some(CodecId::BcjX86Lzma2 | CodecId::BcjArm64Lzma2 | CodecId::Bcj2)
        ),
        "the test binary gets a BCJ codec: {:?}",
        codec_of(&m, "bin/app")
    );
    // Identical files share one frame.
    let frame = |p: &str| match file_entry(&m, p) {
        VerifiedEntry::File { frame, .. } => frame.clone().unwrap(),
        _ => unreachable!(),
    };
    assert_eq!(
        frame("docs/guide/copy-a.txt").offset(),
        frame("shared/copy-b.txt").offset()
    );
    for dir in ["docs", "docs/guide", "shared", "assets", "bin", "empty-dir"] {
        assert!(
            matches!(file_entry(&m, dir), VerifiedEntry::Dir { .. }),
            "{dir} is a dir entry"
        );
    }
    #[cfg(unix)]
    {
        assert!(exec_of(&m, "bin/run.sh"));
        assert!(!exec_of(&m, "docs/guide/intro.txt"));
        assert!(matches!(
            file_entry(&m, "readme"),
            VerifiedEntry::Symlink { target, .. } if target == "docs/guide/intro.txt"
        ));
    }
}

/// Test 3 (and test 4's failure half): every refusal exits 1, writes nothing and leaves no work
/// dir.
#[test]
fn refusals() {
    // Two release keys, both needed; their windows end 365 days after T0.
    let not_after = (T0 + 365 * DAY).to_string();
    let w = World::new(2, 2);
    let dir = w.release_dir("rel", &["--not-after", &not_after]);
    let input = tempfile::tempdir().unwrap();
    write(input.path(), "a.txt", &text(3_000));
    let target = host_target();
    let base = |version: &'static str| Pack {
        input: input.path(),
        version,
        target,
        release_dir: &dir,
        signers: w.all_signers(),
        epoch: T0,
        extra: Vec::new(),
    };
    let refused = |p: &Pack<'_>, what: &str, needle: &str| {
        let out = w.pack(p);
        let err = assert_fails(&out, 1, what);
        assert!(err.contains(needle), "{what}: {err:?} lacks {needle:?}");
        assert!(
            !dir.join(p.version)
                .join(format!("{}.manifest.json", p.target))
                .exists()
                || p.version == "1.0.0",
            "{what}: nothing is written"
        );
        assert_eq!(w.work_dirs(), 0, "{what}: no work dir is left");
    };

    assert_ok(&w.pack(&base("1.0.0")), "first pack");
    refused(&base("1.0.0"), "an existing manifest", "already exists");

    let mut p = base("2.0.0");
    p.signers = vec![spec(&w.root), spec(&w.release[0])];
    refused(&p, "a signer not in the key set", "not in keys.json");

    let mut p = base("2.0.0");
    p.epoch = T0 + 400 * DAY;
    refused(&p, "a signer outside its window", "is not valid at");

    let mut p = base("2.0.0");
    p.signers = vec![spec(&w.release[0])];
    refused(&p, "too few signers", "needs 2 release signer(s), 1 given");

    let mut p = base("2.0.0");
    p.extra = vec!["--app-id", "org.example.other"];
    refused(&p, "another app id", "is not the config's app id");

    assert_ok(&w.pack(&base("1.1.0+build.1")), "pack 1.1.0+build.1");
    refused(
        &base("1.1.0+build.2"),
        "equal precedence, other text",
        "of equal precedence",
    );

    #[cfg(unix)]
    {
        let links = tempfile::tempdir().unwrap();
        write(links.path(), "a.txt", b"x");
        std::os::unix::fs::symlink("a.txt", links.path().join("link")).unwrap();
        let mut p = base("3.0.0");
        p.input = links.path();
        p.target = "windows-x86_64";
        refused(&p, "a symlink on a Windows target", "cannot be packed");

        let fifo = tempfile::tempdir().unwrap();
        write(fifo.path(), "a.txt", b"x");
        let made = std::process::Command::new("mkfifo")
            .arg(fifo.path().join("pipe"))
            .status()
            .expect("run mkfifo");
        assert!(made.success(), "mkfifo");
        let mut p = base("3.0.0");
        p.input = fifo.path();
        refused(&p, "a special file", "special file");
    }
    #[cfg(windows)]
    {
        let mut p = base("3.0.0");
        p.target = "linux-x86_64";
        refused(&p, "a Unix target on a Windows host", "Windows host");
    }
}

/// The work-dir count is a real instrument: the binary does create its work dir under `TMPDIR`
/// (`TMP` on Windows), since a missing one makes the run fail.
#[test]
fn work_dir_goes_under_the_temp_dir() {
    let w = World::new(1, 1);
    let dir = w.release_dir("rel", &[]);
    let input = tempfile::tempdir().unwrap();
    write(input.path(), "a.txt", b"hello");
    let missing = w.dir.path().join("no-such-tmp");
    let out = w.pack_with_tmp(
        &Pack {
            input: input.path(),
            version: "1.0.0",
            target: host_target(),
            release_dir: &dir,
            signers: w.all_signers(),
            epoch: T0,
            extra: Vec::new(),
        },
        &missing,
    );
    let err = assert_fails(&out, 1, "pack with a missing temp dir");
    assert!(err.contains("work dir"), "{err:?}");
}

/// Test 5 (M3-D13): an ordinary non-Rust app's build output, no Cargo file anywhere.
#[test]
fn non_rust_app_layout() {
    let w = World::new(1, 1);
    let dir = w.release_dir("rel", &[]);
    let input = tempfile::tempdir().unwrap();
    let root = input.path();
    write(root, "MyApp.exe", &exe_headers::pe(0x8664, 96 * 1024));
    write(
        root,
        "lib/libfoo.so",
        &exe_headers::elf(183, false, 64 * 1024),
    );
    write(root, "bin/helper.dll", &exe_headers::pe(0xAA64, 64 * 1024));
    write(root, "assets/logo.png", &png(8_000));
    write(
        root,
        "assets/data.json",
        &br#"{"name": "MyApp", "items": [1, 2, 3], "nested": {"ok": true}}"#.repeat(40),
    );
    write(root, "assets/fonts/ui/Regular.txt", &text(5_000));
    write(root, "README.txt", &text(2_500));
    let mut stack = vec![root.to_path_buf()];
    while let Some(d) = stack.pop() {
        for e in fs::read_dir(&d).unwrap() {
            let e = e.unwrap();
            assert!(!e.file_name().to_string_lossy().starts_with("Cargo."));
            if e.file_type().unwrap().is_dir() {
                stack.push(e.path());
            }
        }
    }

    let pack = |target: &'static str| {
        w.pack(&Pack {
            input: root,
            version: "4.0.0",
            target,
            release_dir: &dir,
            signers: w.all_signers(),
            epoch: T0,
            extra: Vec::new(),
        })
    };
    let check = |target: Target| {
        let (m, files) = w.verify(&dir, "4.0.0", target);
        for (path, bytes) in &files {
            assert_eq!(bytes, &read_input(root, path), "{path}");
        }
        assert!(
            matches!(
                codec_of(&m, "MyApp.exe"),
                Some(CodecId::BcjX86Lzma2 | CodecId::Bcj2)
            ),
            "MyApp.exe: {:?}",
            codec_of(&m, "MyApp.exe")
        );
        assert_eq!(codec_of(&m, "lib/libfoo.so"), Some(CodecId::BcjArm64Lzma2));
        assert_eq!(codec_of(&m, "bin/helper.dll"), Some(CodecId::BcjArm64Lzma2));
        assert_eq!(codec_of(&m, "assets/logo.png"), Some(CodecId::Stored));
        for p in [
            "assets/data.json",
            "assets/fonts/ui/Regular.txt",
            "README.txt",
        ] {
            assert_eq!(codec_of(&m, p), Some(CodecId::Lzma2), "{p}");
        }
        assert!(matches!(
            file_entry(&m, "assets/fonts/ui"),
            VerifiedEntry::Dir { .. }
        ));
    };

    assert_ok(&pack("windows-x86_64"), "pack windows-x86_64");
    check(Target::WindowsX86_64);

    let linux = pack("linux-aarch64");
    if cfg!(windows) {
        let err = assert_fails(&linux, 1, "linux-aarch64 on a Windows host");
        assert!(err.contains("Windows host"), "{err:?}");
    } else {
        assert_ok(&linux, "pack linux-aarch64");
        check(Target::LinuxAarch64);
    }
}

// ---- `[update]`, `[install]` and `--runtime` (M5 step 2) -----------------------------------------

/// A 64-bit little-endian ELF as a linker lays out a static executable (`ET_DYN`, one `PT_LOAD`,
/// plus a `PT_INTERP` when `dynamic`), then filler.
#[cfg(unix)]
fn runtime_elf(machine: u16, dynamic: bool) -> Vec<u8> {
    let types: &[u32] = if dynamic { &[1, 3] } else { &[1] };
    let mut h = exe_headers::elf(machine, false, 64 + 56 * types.len() + 4096);
    h[16..18].copy_from_slice(&3u16.to_le_bytes());
    h[32..40].copy_from_slice(&64u64.to_le_bytes());
    h[54..56].copy_from_slice(&56u16.to_le_bytes());
    h[56..58].copy_from_slice(&(types.len() as u16).to_le_bytes());
    for (i, t) in types.iter().enumerate() {
        let at = 64 + 56 * i;
        h[at..at + 4].copy_from_slice(&t.to_le_bytes());
    }
    h
}

#[cfg(unix)]
const UPDATE_TOML: &str = r#"
[update]
feed = "https://updates.example.com/hello"
channel = "stable"
health_timeout_secs = 30

[install]
entry = "bin/app"
name = "Hello"
comment = "Says hello"
icon = "assets/icon.svg"
categories = ["Utility"]
bin = "hello"
"#;

/// An app tree with `entry` marked exec and an SVG icon.
#[cfg(unix)]
fn app_tree(root: &Path, entry: &str) {
    write(root, entry, &exe_headers::elf(62, false, 20_000));
    set_mode(&root.join(entry), 0o755);
    write(
        root,
        "assets/icon.svg",
        b"<svg xmlns='http://www.w3.org/2000/svg'/>",
    );
    write(root, "data/readme.txt", &text(3_000));
}

#[cfg(unix)]
fn pack_update(
    w: &World,
    input: &Path,
    dir: &Path,
    runtime: Option<&Path>,
    version: &'static str,
    target: &'static str,
) -> Output {
    pack_update_ui(w, input, dir, runtime, None, version, target)
}

/// `pack` with `--runtime` and, when given, `--ui` (M6).
#[cfg(unix)]
fn pack_update_ui(
    w: &World,
    input: &Path,
    dir: &Path,
    runtime: Option<&Path>,
    ui: Option<&Path>,
    version: &'static str,
    target: &'static str,
) -> Output {
    let mut extra = Vec::new();
    if let Some(r) = runtime {
        extra.extend_from_slice(&["--runtime", s(r)]);
    }
    if let Some(u) = ui {
        extra.extend_from_slice(&["--ui", s(u)]);
    }
    w.pack(&Pack {
        input,
        version,
        target,
        release_dir: dir,
        signers: w.all_signers(),
        epoch: T0,
        extra,
    })
}

#[cfg(unix)]
fn sha_of(m: &VerifiedManifest, path: &str) -> lunepack_core::Sha256Digest {
    match file_entry(m, path) {
        VerifiedEntry::File { sha256, .. } => *sha256,
        _ => panic!("{path} is not a file"),
    }
}

/// The runtime is placed beside the entry, the config at the root, both hashed into the manifest;
/// the config decodes to the document the config file describes; `verify` accepts the release.
#[cfg(unix)]
#[test]
fn update_pack_places_runtime_and_config() {
    for (entry, runtime_at) in [
        ("bin/app", "bin/lunepack-runtime"),
        ("app", "lunepack-runtime"),
    ] {
        let w = World::new(1, 1);
        let toml = UPDATE_TOML.replace("bin/app", entry);
        w.append_config(&toml);
        let dir = w.release_dir("rel", &[]);
        let input = tempfile::tempdir().unwrap();
        app_tree(input.path(), entry);
        let runtime = w.dir.path().join("runtime");
        let runtime_bytes = runtime_elf(62, false);
        fs::write(&runtime, &runtime_bytes).unwrap();

        let out = pack_update(
            &w,
            input.path(),
            &dir,
            Some(&runtime),
            "1.2.3",
            "linux-x86_64",
        );
        assert_ok(&out, "pack with [update]");
        assert!(stdout(&out).contains("update: placed"), "{}", stdout(&out));
        // The input is never touched.
        assert!(!input.path().join(runtime_at).exists());
        assert!(!input.path().join("lunepack-update.json").exists());

        let (m, files) = w.verify(&dir, "1.2.3", Target::LinuxX86_64);
        assert_eq!(files[runtime_at], runtime_bytes, "{entry}: the runtime");
        assert!(exec_of(&m, runtime_at), "{entry}: the runtime is exec");
        assert!(exec_of(&m, entry));
        let config_bytes = &files["lunepack-update.json"];
        assert_eq!(
            sha_of(&m, "lunepack-update.json"),
            Sha256Hasher.sha256(config_bytes),
            "{entry}: the manifest's hash is the written bytes'"
        );
        assert!(!files.contains_key("assets/lunepack-update.json"));
        let doc = lunepack_core::UpdateConfig::parse(config_bytes).unwrap();
        assert_eq!(doc.app_id.as_str(), APP);
        assert_eq!(doc.version.to_string(), "1.2.3");
        assert_eq!(doc.target, Target::LinuxX86_64);
        assert_eq!(doc.feed, "https://updates.example.com/hello/");
        assert_eq!(doc.channel.as_str(), "stable");
        assert_eq!(doc.health_timeout_secs, 30);
        assert_eq!(doc.root.threshold, 1);
        assert_eq!(doc.root.keys.len(), 1);
        assert_eq!(doc.install.entry.as_str(), entry);
        assert_eq!(doc.install.name, "Hello");
        assert_eq!(doc.install.comment.as_deref(), Some("Says hello"));
        assert_eq!(
            doc.install.icon.as_ref().map(|i| i.as_str()),
            Some("assets/icon.svg")
        );
        assert_eq!(doc.install.categories, ["Utility"]);
        assert_eq!(doc.install.bin.as_deref(), Some("hello"));
        assert!(!doc.install.terminal);

        // `verify` accepts the release once a feed lists it, and `inspect` shows nothing new.
        let signer = spec(&w.release[0]);
        let epoch = T0.to_string();
        let publisher = w.dir.path().join("rel.publisher/lunepack.toml");
        let added = w.cmd(
            &[
                "--config",
                s(&publisher),
                "feed",
                "add",
                "--release-dir",
                s(&dir),
                "--channel",
                "stable",
                "--version",
                "1.2.3",
                "--sign",
                &signer,
            ],
            &[("SOURCE_DATE_EPOCH", &epoch)],
        );
        assert_ok(&added, "feed add");
        let at = (T0 + 60).to_string();
        let verified = w.run(&["verify", s(&dir), "--at", &at], &[]);
        assert_ok(&verified, "verify");
        let inspected = w.run(&["inspect", s(&dir), "--at", &at], &[]);
        assert_ok(&inspected, "inspect");
        assert!(!stdout(&inspected).contains("lunepack-runtime"));
    }
}

/// `[install] publisher` (M6-D3) is written into the signed config; absent stays absent; a bad
/// value is refused naming the field.
#[cfg(unix)]
#[test]
fn update_pack_writes_the_publisher() {
    let pack_with = |toml: &str| {
        let w = World::new(1, 1);
        w.append_config(toml);
        let dir = w.release_dir("rel", &[]);
        let input = tempfile::tempdir().unwrap();
        app_tree(input.path(), "bin/app");
        let runtime = w.dir.path().join("runtime");
        fs::write(&runtime, runtime_elf(62, false)).unwrap();
        let out = pack_update(
            &w,
            input.path(),
            &dir,
            Some(&runtime),
            "1.0.0",
            "linux-x86_64",
        );
        (w, dir, out)
    };
    let (w, dir, out) = pack_with(&UPDATE_TOML.replace(
        "comment = \"Says hello\"",
        "comment = \"Says hello\"\npublisher = \"Acme\"",
    ));
    assert_ok(&out, "pack with a publisher");
    let (_, files) = w.verify(&dir, "1.0.0", Target::LinuxX86_64);
    let doc = lunepack_core::UpdateConfig::parse(&files["lunepack-update.json"]).unwrap();
    assert_eq!(doc.install.publisher.as_deref(), Some("Acme"));

    let (w, dir, out) = pack_with(UPDATE_TOML);
    assert_ok(&out, "pack without a publisher");
    let (_, files) = w.verify(&dir, "1.0.0", Target::LinuxX86_64);
    let bytes = &files["lunepack-update.json"];
    assert!(!String::from_utf8_lossy(bytes).contains("publisher"));
    let doc = lunepack_core::UpdateConfig::parse(bytes).unwrap();
    assert_eq!(doc.install.publisher, None);

    let (_w, _dir, out) =
        pack_with(&UPDATE_TOML.replace("comment = \"Says hello\"", "publisher = \"Ac\\\\me\""));
    let err = assert_fails(&out, 1, "a publisher with a backslash");
    assert!(err.contains("[install] publisher"), "{err:?}");
}

/// `[install] file_types`, `url_schemes` and `autostart` (M7-D3) are written into the signed
/// config; absent stays absent; a refused value is named by member, never shown.
#[cfg(unix)]
#[test]
fn update_pack_writes_the_declarations() {
    let pack_with = |toml: &str| {
        let w = World::new(1, 1);
        w.append_config(toml);
        let dir = w.release_dir("rel", &[]);
        let input = tempfile::tempdir().unwrap();
        app_tree(input.path(), "bin/app");
        let runtime = w.dir.path().join("runtime");
        fs::write(&runtime, runtime_elf(62, false)).unwrap();
        let out = pack_update(
            &w,
            input.path(),
            &dir,
            Some(&runtime),
            "1.0.0",
            "linux-x86_64",
        );
        (w, dir, out)
    };
    let declared = |extra: &str| {
        UPDATE_TOML.replace("bin = \"hello\"\n", &format!("bin = \"hello\"\n{extra}"))
    };
    let (w, dir, out) = pack_with(&declared(
        "url_schemes = [\"hello\", \"hello-x\"]\nautostart = true\n\n\
         [[install.file_types]]\next = \"hello\"\nmime = \"application/x-hello\"\nname = \"Hello file\"\n",
    ));
    assert_ok(&out, "pack with declarations");
    let (_, files) = w.verify(&dir, "1.0.0", Target::LinuxX86_64);
    let doc = lunepack_core::UpdateConfig::parse(&files["lunepack-update.json"]).unwrap();
    assert_eq!(doc.install.url_schemes, ["hello", "hello-x"]);
    assert!(doc.install.autostart);
    assert_eq!(doc.install.file_types.len(), 1);
    assert_eq!(doc.install.file_types[0].mime, "application/x-hello");

    let (w, dir, out) = pack_with(UPDATE_TOML);
    assert_ok(&out, "pack without declarations");
    let (_, files) = w.verify(&dir, "1.0.0", Target::LinuxX86_64);
    let text = String::from_utf8_lossy(&files["lunepack-update.json"]).into_owned();
    for key in ["file_types", "url_schemes", "autostart"] {
        assert!(!text.contains(key), "{key}");
    }
    drop(w);

    let (_w, _dir, out) = pack_with(&declared("url_schemes = [\"https\"]\n"));
    let err = assert_fails(&out, 1, "a denied scheme");
    assert!(err.contains("[install] url_schemes"), "{err:?}");
    assert!(!err.contains("https"), "{err:?}");
    let (_w, _dir, out) = pack_with(&declared(
        "\n[[install.file_types]]\next = \"hello\"\nmime = \"a/b;c/d\"\nname = \"n\"\n",
    ));
    let err = assert_fails(&out, 1, "a mime with a semicolon");
    assert!(err.contains("[install] file_types"), "{err:?}");
}

/// C2: the same inputs (the runtime's bytes included), keys and clock give identical bytes; a
/// different runtime gives a different pack.
#[cfg(unix)]
#[test]
fn update_pack_is_deterministic() {
    let w = World::new(1, 1);
    w.append_config(UPDATE_TOML);
    let input = tempfile::tempdir().unwrap();
    app_tree(input.path(), "bin/app");
    let runtime = w.dir.path().join("runtime");
    fs::write(&runtime, runtime_elf(62, false)).unwrap();
    let (a, b) = (w.release_dir("a", &[]), w.release_dir("b", &[]));
    for dir in [&a, &b] {
        assert_ok(
            &pack_update(
                &w,
                input.path(),
                dir,
                Some(&runtime),
                "1.0.0",
                "linux-x86_64",
            ),
            "pack",
        );
    }
    for name in [
        "1.0.0/linux-x86_64.pack",
        "1.0.0/linux-x86_64.manifest.json",
    ] {
        assert_eq!(
            fs::read(a.join(name)).unwrap(),
            fs::read(b.join(name)).unwrap(),
            "{name}"
        );
    }
    let other = w.dir.path().join("runtime2");
    let mut changed = runtime_elf(62, false);
    *changed.last_mut().unwrap() ^= 0xFF;
    fs::write(&other, &changed).unwrap();
    let c = w.release_dir("c", &[]);
    assert_ok(
        &pack_update(&w, input.path(), &c, Some(&other), "1.0.0", "linux-x86_64"),
        "pack with another runtime",
    );
    assert_ne!(
        fs::read(a.join("1.0.0/linux-x86_64.manifest.json")).unwrap(),
        fs::read(c.join("1.0.0/linux-x86_64.manifest.json")).unwrap()
    );
}

/// Every refusal exits 1, names the field or flag and not its value, writes nothing and leaves no
/// work dir.
#[cfg(unix)]
#[test]
fn update_pack_refusals() {
    let w = World::new(1, 1);
    w.append_config(UPDATE_TOML);
    let dir = w.release_dir("rel", &[]);
    let good = tempfile::tempdir().unwrap();
    app_tree(good.path(), "bin/app");
    let runtime = w.dir.path().join("runtime");
    fs::write(&runtime, runtime_elf(62, false)).unwrap();
    let refused = |input: &Path, rt: Option<&Path>, target: &'static str, needle: &str| {
        let out = pack_update(&w, input, &dir, rt, "1.0.0", target);
        let err = assert_fails(&out, 1, needle);
        assert!(err.contains(needle), "{err:?} lacks {needle:?}");
        assert!(
            !dir.join("1.0.0")
                .join(format!("{target}.manifest.json"))
                .exists()
        );
        assert!(!dir.join("1.0.0").join(format!("{target}.pack")).exists());
        assert_eq!(w.work_dirs(), 0, "{needle}: no work dir is left");
        err
    };

    refused(good.path(), None, "linux-x86_64", "--runtime is required");

    // A dynamic ELF, and an arm64 ELF for linux-x86_64.
    let dynamic = w.dir.path().join("dynamic");
    fs::write(&dynamic, runtime_elf(62, true)).unwrap();
    refused(
        good.path(),
        Some(&dynamic),
        "linux-x86_64",
        "must be static",
    );
    let arm = w.dir.path().join("arm");
    fs::write(&arm, runtime_elf(183, false)).unwrap();
    refused(
        good.path(),
        Some(&arm),
        "linux-x86_64",
        "another architecture",
    );
    let junk = w.dir.path().join("junk");
    fs::write(&junk, b"not an executable").unwrap();
    refused(
        good.path(),
        Some(&junk),
        "linux-x86_64",
        "not an executable",
    );

    // Reserved names: the root config, one deeper, a directory of that name, and the runtime and
    // the UI beside the entry (either form, any case), with or without `--ui`.
    for (rel, is_dir) in [
        ("lunepack-update.json", false),
        ("assets/lunepack-update.json", false),
        ("data/deep/Lunepack-Update.JSON", false),
        ("data/lunepack-update.json", true),
        ("bin/lunepack-runtime", false),
        ("bin/lunepack-runtime.exe", false),
        ("bin/LUNEPACK-RUNTIME", false),
        ("bin/lunepack-ui", false),
        ("bin/lunepack-ui.exe", false),
        ("bin/LUNEPACK-UI", false),
    ] {
        let input = tempfile::tempdir().unwrap();
        app_tree(input.path(), "bin/app");
        if is_dir {
            fs::create_dir_all(input.path().join(rel)).unwrap();
        } else {
            write(input.path(), rel, b"x");
        }
        refused(input.path(), Some(&runtime), "linux-x86_64", "reserved");
    }
    // The runtime's name away from the entry's directory is an ordinary file.
    let input = tempfile::tempdir().unwrap();
    app_tree(input.path(), "bin/app");
    write(input.path(), "tools/lunepack-runtime", b"x");
    assert_ok(
        &pack_update(
            &w,
            input.path(),
            &dir,
            Some(&runtime),
            "2.0.0",
            "linux-x86_64",
        ),
        "a runtime-named file elsewhere",
    );

    // An entry that is missing, not exec, a directory or a symlink; an icon that is missing.
    let input = tempfile::tempdir().unwrap();
    write(input.path(), "assets/icon.svg", b"<svg/>");
    let err = refused(
        input.path(),
        Some(&runtime),
        "linux-x86_64",
        "install.entry",
    );
    assert!(!err.contains("bin/app"), "the value is not echoed: {err:?}");
    write(input.path(), "bin/app", b"#!/bin/sh\n");
    refused(
        input.path(),
        Some(&runtime),
        "linux-x86_64",
        "not marked executable",
    );
    fs::remove_file(input.path().join("bin/app")).unwrap();
    fs::create_dir(input.path().join("bin/app")).unwrap();
    refused(
        input.path(),
        Some(&runtime),
        "linux-x86_64",
        "install.entry",
    );
    fs::remove_dir(input.path().join("bin/app")).unwrap();
    write(input.path(), "bin/real", b"#!/bin/sh\n");
    set_mode(&input.path().join("bin/real"), 0o755);
    std::os::unix::fs::symlink("real", input.path().join("bin/app")).unwrap();
    refused(
        input.path(),
        Some(&runtime),
        "linux-x86_64",
        "install.entry",
    );
    let input = tempfile::tempdir().unwrap();
    app_tree(input.path(), "bin/app");
    fs::remove_file(input.path().join("assets/icon.svg")).unwrap();
    refused(input.path(), Some(&runtime), "linux-x86_64", "install.icon");
}

/// The feed rule at pack time: a plain-http non-loopback feed is refused, naming the field and the
/// rule and not the value; a loopback literal packs.
#[cfg(unix)]
#[test]
fn update_pack_feed_rule() {
    let input = tempfile::tempdir().unwrap();
    app_tree(input.path(), "bin/app");
    for (feed, ok) in [
        ("http://example.com/", false),
        ("http://localhost:8080/", false),
        ("https://user@example.com/", false),
        ("https://example.com/a?x=1", false),
        ("http://127.0.0.1:8080/", true),
        ("file:///srv/releases/", true),
    ] {
        let w = World::new(1, 1);
        let toml = UPDATE_TOML.replace("https://updates.example.com/hello", feed);
        w.append_config(&toml);
        let dir = w.release_dir("rel", &[]);
        let runtime = w.dir.path().join("runtime");
        fs::write(&runtime, runtime_elf(62, false)).unwrap();
        let out = pack_update(
            &w,
            input.path(),
            &dir,
            Some(&runtime),
            "1.0.0",
            "linux-x86_64",
        );
        if ok {
            assert_ok(&out, feed);
            let (_, files) = w.verify(&dir, "1.0.0", Target::LinuxX86_64);
            let doc = lunepack_core::UpdateConfig::parse(&files["lunepack-update.json"]).unwrap();
            assert_eq!(doc.feed, feed);
        } else {
            let err = assert_fails(&out, 1, feed);
            assert!(err.contains("[update] feed"), "{feed}: {err:?}");
            assert!(
                !err.contains("example.com") && !err.contains("localhost"),
                "{err:?}"
            );
            assert!(!dir.join("1.0.0").exists());
            assert_eq!(w.work_dirs(), 0);
        }
    }
}

/// `--ui` (M6) places the UI beside the runtime, exec, hashed and packed like any file. A
/// dynamic (glibc) ELF is accepted for the UI; the release verifies.
#[cfg(unix)]
#[test]
fn ui_pack_places_ui_beside_runtime() {
    for (entry, ui_at) in [("bin/app", "bin/lunepack-ui"), ("app", "lunepack-ui")] {
        let w = World::new(1, 1);
        w.append_config(&UPDATE_TOML.replace("bin/app", entry));
        let dir = w.release_dir("rel", &[]);
        let input = tempfile::tempdir().unwrap();
        app_tree(input.path(), entry);
        let runtime = w.dir.path().join("runtime");
        fs::write(&runtime, runtime_elf(62, false)).unwrap();
        let ui = w.dir.path().join("ui");
        let ui_bytes = runtime_elf(62, true);
        fs::write(&ui, &ui_bytes).unwrap();

        let out = pack_update_ui(
            &w,
            input.path(),
            &dir,
            Some(&runtime),
            Some(&ui),
            "1.2.3",
            "linux-x86_64",
        );
        assert_ok(&out, "pack with --ui");
        assert!(!input.path().join(ui_at).exists());

        let (m, files) = w.verify(&dir, "1.2.3", Target::LinuxX86_64);
        assert_eq!(files[ui_at], ui_bytes, "{entry}: the UI");
        assert!(exec_of(&m, ui_at), "{entry}: the UI is exec");
        assert_eq!(sha_of(&m, ui_at), Sha256Hasher.sha256(&ui_bytes));
        assert!(files.contains_key("lunepack-update.json"));
    }
}

/// C2 with `--ui`: the same inputs give identical bytes, and the UI changes the manifest.
#[cfg(unix)]
#[test]
fn ui_pack_is_deterministic() {
    let w = World::new(1, 1);
    w.append_config(UPDATE_TOML);
    let input = tempfile::tempdir().unwrap();
    app_tree(input.path(), "bin/app");
    let runtime = w.dir.path().join("runtime");
    fs::write(&runtime, runtime_elf(62, false)).unwrap();
    let ui = w.dir.path().join("ui");
    fs::write(&ui, runtime_elf(62, true)).unwrap();
    let (a, b, plain) = (
        w.release_dir("a", &[]),
        w.release_dir("b", &[]),
        w.release_dir("plain", &[]),
    );
    for dir in [&a, &b] {
        assert_ok(
            &pack_update_ui(
                &w,
                input.path(),
                dir,
                Some(&runtime),
                Some(&ui),
                "1.0.0",
                "linux-x86_64",
            ),
            "pack with --ui",
        );
    }
    assert_ok(
        &pack_update(
            &w,
            input.path(),
            &plain,
            Some(&runtime),
            "1.0.0",
            "linux-x86_64",
        ),
        "pack without --ui",
    );
    for name in [
        "1.0.0/linux-x86_64.pack",
        "1.0.0/linux-x86_64.manifest.json",
    ] {
        assert_eq!(
            fs::read(a.join(name)).unwrap(),
            fs::read(b.join(name)).unwrap(),
            "{name}"
        );
    }
    assert_ne!(
        fs::read(a.join("1.0.0/linux-x86_64.manifest.json")).unwrap(),
        fs::read(plain.join("1.0.0/linux-x86_64.manifest.json")).unwrap()
    );
}

/// `--ui` refusals: without `--runtime`, without `[update]`, a non-regular file, a file over the
/// cap, a wrong architecture and a non-executable. Each exits 1, writes nothing, leaves no work dir.
#[cfg(unix)]
#[test]
fn ui_pack_refusals() {
    let w = World::new(1, 1);
    w.append_config(UPDATE_TOML);
    let dir = w.release_dir("rel", &[]);
    let good = tempfile::tempdir().unwrap();
    app_tree(good.path(), "bin/app");
    let runtime = w.dir.path().join("runtime");
    fs::write(&runtime, runtime_elf(62, false)).unwrap();
    let refused = |rt: Option<&Path>, ui: &Path, needle: &str| {
        let out = pack_update_ui(&w, good.path(), &dir, rt, Some(ui), "1.0.0", "linux-x86_64");
        let err = assert_fails(&out, 1, needle);
        assert!(err.contains(needle), "{err:?} lacks {needle:?}");
        assert!(!dir.join("1.0.0").exists());
        assert_eq!(w.work_dirs(), 0, "{needle}: no work dir is left");
    };
    let ui = w.dir.path().join("ui");
    fs::write(&ui, runtime_elf(62, true)).unwrap();
    refused(None, &ui, "--ui needs --runtime");

    let arm = w.dir.path().join("ui-arm");
    fs::write(&arm, runtime_elf(183, true)).unwrap();
    refused(Some(&runtime), &arm, "another architecture");
    let junk = w.dir.path().join("ui-junk");
    fs::write(&junk, b"not an executable").unwrap();
    refused(Some(&runtime), &junk, "not an executable");
    let dir_ui = w.dir.path().join("ui-dir");
    fs::create_dir(&dir_ui).unwrap();
    refused(Some(&runtime), &dir_ui, "is not a regular file");
    let big = w.dir.path().join("ui-big");
    fs::File::create(&big)
        .unwrap()
        .set_len(64 * 1024 * 1024 + 1)
        .unwrap();
    refused(Some(&runtime), &big, "is over");

    // Without [update] the flag is refused, and the tree is packed as in M3 when it is left out.
    let plain = World::new(1, 1);
    let plain_dir = plain.release_dir("rel", &[]);
    let out = pack_update_ui(
        &plain,
        good.path(),
        &plain_dir,
        None,
        Some(&ui),
        "1.0.0",
        "linux-x86_64",
    );
    let err = assert_fails(&out, 1, "--ui without [update]");
    assert!(err.contains("--ui needs [update]"), "{err:?}");
    assert!(!plain_dir.join("1.0.0").exists());
    assert_eq!(plain.work_dirs(), 0);
}

/// The config tables: `--runtime` without `[update]`, `[update]` without `[install]`, and the
/// other way round, are errors; an app with neither packs as before; bad `[install]` values name
/// their field.
#[cfg(unix)]
#[test]
fn update_config_tables() {
    let input = tempfile::tempdir().unwrap();
    app_tree(input.path(), "bin/app");

    // No [update]: --runtime is refused, and the tree is packed as in M3.
    let w = World::new(1, 1);
    let dir = w.release_dir("rel", &[]);
    let runtime = w.dir.path().join("runtime");
    fs::write(&runtime, runtime_elf(62, false)).unwrap();
    let out = pack_update(
        &w,
        input.path(),
        &dir,
        Some(&runtime),
        "1.0.0",
        "linux-x86_64",
    );
    let err = assert_fails(&out, 1, "--runtime without [update]");
    assert!(err.contains("--runtime needs [update]"), "{err:?}");
    assert!(!dir.join("1.0.0").exists());
    assert_ok(
        &pack_update(&w, input.path(), &dir, None, "1.0.0", "linux-x86_64"),
        "pack without [update]",
    );
    let (_, files) = w.verify(&dir, "1.0.0", Target::LinuxX86_64);
    assert!(!files.contains_key("lunepack-update.json"));
    assert!(!files.contains_key("bin/lunepack-runtime"));

    let broken = |toml: &str, needle: &str| {
        let w = World::new(1, 1);
        w.append_config(toml);
        let out = w.run(&["verify", s(w.dir.path())], &[]);
        let err = assert_fails(&out, 1, needle);
        assert!(err.contains(needle), "{err:?} lacks {needle:?}");
    };
    broken(
        "[update]\nfeed = \"https://example.com/\"\n",
        "[update] needs [install]",
    );
    broken(
        "[install]\nentry = \"app\"\nname = \"A\"\n",
        "[install] needs [update]",
    );
    broken(
        "[update]\nfeed = \"https://example.com/\"\nhealth_timeout_secs = 4\n[install]\nentry = \"app\"\nname = \"A\"\n",
        "health_timeout_secs",
    );
    broken(
        "[update]\nfeed = \"https://example.com/\"\n[install]\nentry = \"/abs\"\nname = \"A\"\n",
        "install.entry",
    );
    broken(
        "[update]\nfeed = \"https://example.com/\"\nbogus = 1\n[install]\nentry = \"app\"\nname = \"A\"\n",
        "unknown field",
    );
    // A value the core refuses is named by its field at pack time.
    let w = World::new(1, 1);
    w.append_config(&UPDATE_TOML.replace("name = \"Hello\"", "name = \"Hel\\\\lo\""));
    let dir = w.release_dir("rel", &[]);
    let runtime = w.dir.path().join("runtime");
    fs::write(&runtime, runtime_elf(62, false)).unwrap();
    let out = pack_update(
        &w,
        input.path(),
        &dir,
        Some(&runtime),
        "1.0.0",
        "linux-x86_64",
    );
    let err = assert_fails(&out, 1, "a name with a backslash");
    assert!(err.contains("[install] name"), "{err:?}");
}

/// Windows and macOS targets: the runtime's name and the config's place follow the target (a
/// Windows runtime must carry M7-D10's hardening; macOS: the header-class check only), and the exec
/// bit of a Windows entry is not required.
#[cfg(unix)]
#[test]
fn update_pack_other_targets() {
    let w = World::new(1, 1);
    w.append_config(&UPDATE_TOML.replace("bin/app", "bin/app.exe"));
    let dir = w.release_dir("rel", &[]);
    let input = tempfile::tempdir().unwrap();
    write(input.path(), "bin/app.exe", &exe_headers::pe(0x8664, 8_000));
    write(input.path(), "assets/icon.svg", b"<svg/>");

    let pe = w.dir.path().join("runtime.exe");
    fs::write(&pe, hardened_pe(0x8664, 2)).unwrap();
    let stub = w.dir.path().join("stub.exe");
    fs::write(&stub, hardened_pe(0x8664, 2)).unwrap();
    assert_ok(
        &pack_win(
            &w,
            input.path(),
            &dir,
            Some(&pe),
            Some(&stub),
            "1.0.0",
            "windows-x86_64",
        ),
        "windows-x86_64",
    );
    let (_, files) = w.verify(&dir, "1.0.0", Target::WindowsX86_64);
    assert!(files.contains_key("bin/lunepack-runtime.exe"));
    assert!(files.contains_key("bin/lunepack-stub.exe"));
    assert!(files.contains_key("lunepack-update.json"));

    // A Linux runtime for a Windows target, and an arm64 PE for x86-64, are refused.
    let elf = w.dir.path().join("runtime.elf");
    fs::write(&elf, runtime_elf(62, false)).unwrap();
    let out = pack_win(
        &w,
        input.path(),
        &dir,
        Some(&elf),
        Some(&stub),
        "1.0.1",
        "windows-x86_64",
    );
    assert_fails(&out, 1, "an ELF for a Windows target");
    let arm = w.dir.path().join("arm.exe");
    fs::write(&arm, hardened_pe(0xAA64, 2)).unwrap();
    let out = pack_win(
        &w,
        input.path(),
        &dir,
        Some(&arm),
        Some(&stub),
        "1.0.1",
        "windows-x86_64",
    );
    let err = assert_fails(&out, 1, "an arm64 PE for windows-x86_64");
    assert!(err.contains("another architecture"), "{err:?}");
    // The header-only PE of earlier milestones, and a runtime without the hardening (M7-D10).
    let bare = w.dir.path().join("bare.exe");
    fs::write(&bare, exe_headers::pe(0x8664, 4_096)).unwrap();
    let out = pack_win(
        &w,
        input.path(),
        &dir,
        Some(&bare),
        Some(&stub),
        "1.0.1",
        "windows-x86_64",
    );
    let err = assert_fails(&out, 1, "a header-only PE");
    assert!(
        err.contains("PE headers or tables are malformed"),
        "{err:?}"
    );
    let crt = w.dir.path().join("crt.exe");
    let mut spec = exe_headers::PeSpec::hardened(2);
    spec.imports.push("VCRUNTIME140.dll".to_owned());
    fs::write(&crt, exe_headers::pe_image(0x8664, &spec)).unwrap();
    let out = pack_win(
        &w,
        input.path(),
        &dir,
        Some(&crt),
        Some(&stub),
        "1.0.1",
        "windows-x86_64",
    );
    let err = assert_fails(&out, 1, "a runtime importing the C runtime DLL");
    assert!(err.contains("C runtime"), "{err:?}");

    // macOS: the config sits under Contents/Resources (assumed until M8).
    let w = World::new(1, 1);
    w.append_config(&UPDATE_TOML.replace("bin/app", "App.app/Contents/MacOS/app"));
    let dir = w.release_dir("rel", &[]);
    let input = tempfile::tempdir().unwrap();
    write(
        input.path(),
        "App.app/Contents/MacOS/app",
        &exe_headers::macho(0x0100_000C, false, 8_000),
    );
    set_mode(&input.path().join("App.app/Contents/MacOS/app"), 0o755);
    write(input.path(), "assets/icon.svg", b"<svg/>");
    let macho = w.dir.path().join("runtime.macho");
    fs::write(&macho, exe_headers::macho(0x0100_000C, false, 4_096)).unwrap();
    assert_ok(
        &pack_update(
            &w,
            input.path(),
            &dir,
            Some(&macho),
            "1.0.0",
            "macos-aarch64",
        ),
        "macos-aarch64",
    );
    let (_, files) = w.verify(&dir, "1.0.0", Target::MacosAarch64);
    assert!(files.contains_key("App.app/Contents/MacOS/lunepack-runtime"));
    assert!(files.contains_key("Contents/Resources/lunepack-update.json"));
}

// ---- `--stub` and stamping for Windows targets (M7 step 12) -------------------------------------

/// A hardened PE image (M7-D10) of `machine` with the GUI (2) or console (3) `subsystem`.
#[cfg(unix)]
fn hardened_pe(machine: u16, subsystem: u16) -> Vec<u8> {
    exe_headers::pe_image(machine, &exe_headers::PeSpec::hardened(subsystem))
}

/// `pack` for a Windows target with `--runtime` and `--stub` as given.
#[cfg(unix)]
fn pack_win(
    w: &World,
    input: &Path,
    dir: &Path,
    runtime: Option<&Path>,
    stub: Option<&Path>,
    version: &'static str,
    target: &'static str,
) -> Output {
    let mut extra = Vec::new();
    if let Some(r) = runtime {
        extra.extend_from_slice(&["--runtime", s(r)]);
    }
    if let Some(p) = stub {
        extra.extend_from_slice(&["--stub", s(p)]);
    }
    w.pack(&Pack {
        input,
        version,
        target,
        release_dir: dir,
        signers: w.all_signers(),
        epoch: T0,
        extra,
    })
}

/// A header-only PNG of `side` by `side` pixels (the packager reads the header and no pixel).
#[cfg(unix)]
fn icon_png(side: u32) -> Vec<u8> {
    let mut p = b"\x89PNG\r\n\x1a\n".to_vec();
    p.extend_from_slice(&13u32.to_be_bytes());
    p.extend_from_slice(b"IHDR");
    p.extend_from_slice(&side.to_be_bytes());
    p.extend_from_slice(&side.to_be_bytes());
    p.extend_from_slice(&[8, 6, 0, 0, 0, 0, 0, 0, 0]);
    p
}

/// A Windows app: an `.exe` entry, an SVG icon, some data; the config has `[update]`.
#[cfg(unix)]
struct WinApp {
    w: World,
    input: tempfile::TempDir,
    runtime: PathBuf,
    stub: PathBuf,
}

#[cfg(unix)]
fn win_app(toml: &str) -> WinApp {
    let w = World::new(1, 1);
    w.append_config(toml);
    let input = tempfile::tempdir().unwrap();
    write(input.path(), "bin/app.exe", &exe_headers::pe(0x8664, 8_000));
    write(input.path(), "assets/icon.svg", b"<svg/>");
    write(input.path(), "data/readme.txt", &text(3_000));
    let runtime = w.dir.path().join("runtime.exe");
    fs::write(&runtime, hardened_pe(0x8664, 2)).unwrap();
    let stub = w.dir.path().join("stub.exe");
    fs::write(&stub, hardened_pe(0x8664, 2)).unwrap();
    WinApp {
        w,
        input,
        runtime,
        stub,
    }
}

#[cfg(unix)]
const WIN_TOML: &str = r#"
[update]
feed = "https://updates.example.com/hello"
channel = "stable"
health_timeout_secs = 30

[install]
entry = "bin/app.exe"
name = "Hello"
publisher = "Example Org"
icon = "assets/icon.svg"
"#;

#[cfg(unix)]
impl WinApp {
    fn pack(&self, dir: &Path, version: &'static str, stub: Option<&Path>) -> Output {
        pack_win(
            &self.w,
            self.input.path(),
            dir,
            Some(&self.runtime),
            stub,
            version,
            "windows-x86_64",
        )
    }

    /// The stub as the pack holds it.
    fn stub_in(&self, dir: &Path, version: &str) -> Vec<u8> {
        let (_, mut files) = self.w.verify(dir, version, Target::WindowsX86_64);
        files.remove("bin/lunepack-stub.exe").expect("a stub")
    }
}

/// The VERSIONINFO strings of a PE, by key.
#[cfg(unix)]
fn version_strings(pe: &[u8]) -> BTreeMap<String, String> {
    let image = editpe::Image::parse(pe.to_vec()).unwrap();
    let info = image
        .resource_directory()
        .and_then(|r| r.get_version_info().ok().flatten())
        .expect("a version info");
    info.strings[0]
        .strings
        .iter()
        .map(|(k, v)| (k.clone(), v.clone()))
        .collect()
}

/// M7-D14: the stub is stamped (name, publisher, version, original file name, the icon) and placed
/// beside the entry before hashing; the stamped bytes keep every hardening field of the input
/// (P3) and pass the stub check again.
#[cfg(unix)]
#[test]
fn windows_pack_stamps_and_places_the_stub() {
    let app = win_app(WIN_TOML);
    let dir = app.w.release_dir("rel", &[]);
    assert_ok(&app.pack(&dir, "1.2.3-rc.1+b7", Some(&app.stub)), "pack");
    let stamped = app.stub_in(&dir, "1.2.3-rc.1+b7");
    let input = fs::read(&app.stub).unwrap();
    assert_ne!(stamped, input);
    lunepack_core::check_pe_stub(&stamped, Target::WindowsX86_64, false).expect("a GUI stub");
    let (before, after) = (
        lunepack_core::pe::PeImage::parse(&input).unwrap(),
        lunepack_core::pe::PeImage::parse(&stamped).unwrap(),
    );
    assert_eq!(after.headers.machine, before.headers.machine);
    assert_eq!(after.headers.subsystem, before.headers.subsystem);
    assert_eq!(after.imports, before.imports);
    assert_eq!(after.delay_imports, before.delay_imports);
    assert_eq!(after.dependent_load_flags, Some(0x800));
    assert_eq!(after.manifest, before.manifest);
    let strings = version_strings(&stamped);
    for (key, value) in [
        ("CompanyName", "Example Org"),
        ("FileDescription", "Hello"),
        ("FileVersion", "1.2.3-rc.1+b7"),
        ("OriginalFilename", "app.exe"),
        ("ProductName", "Hello"),
        ("ProductVersion", "1.2.3-rc.1+b7"),
    ] {
        assert_eq!(strings.get(key).map(String::as_str), Some(value), "{key}");
    }
    // An SVG `install.icon` stamps no icon.
    let image = editpe::Image::parse(stamped.clone()).unwrap();
    assert!(
        image
            .resource_directory()
            .unwrap()
            .get_main_icon()
            .unwrap()
            .is_none()
    );

    // No publisher: no CompanyName.
    let app = win_app(&WIN_TOML.replace("publisher = \"Example Org\"\n", ""));
    let dir = app.w.release_dir("rel", &[]);
    assert_ok(&app.pack(&dir, "1.0.0", Some(&app.stub)), "pack");
    let strings = version_strings(&app.stub_in(&dir, "1.0.0"));
    assert!(!strings.contains_key("CompanyName"), "{strings:?}");
}

/// The icon: `[windows] icon` (an ICO) wins; else a square PNG `install.icon` (at most 256 px) is
/// wrapped as a PNG-in-ICO entry; an SVG gives none; a PNG that breaks the rule is an error.
#[cfg(unix)]
#[test]
fn windows_stub_icon_follows_m7_d14() {
    let icon_bytes = |pe: &[u8]| {
        let image = editpe::Image::parse(pe.to_vec()).unwrap();
        image
            .resource_directory()
            .unwrap()
            .get_main_icon()
            .unwrap()
            .map(<[u8]>::to_vec)
    };
    // A PNG install.icon, 64 px: wrapped, the PNG's bytes inside.
    let toml = WIN_TOML.replace("assets/icon.svg", "assets/icon.png");
    let app = win_app(&toml);
    write(app.input.path(), "assets/icon.png", &icon_png(64));
    let dir = app.w.release_dir("rel", &[]);
    assert_ok(&app.pack(&dir, "1.0.0", Some(&app.stub)), "png icon");
    let icon = icon_bytes(&app.stub_in(&dir, "1.0.0")).expect("an icon");
    assert!(
        icon.ends_with(&icon_png(64)),
        "the PNG is carried unchanged"
    );

    // 256 px is allowed, 257 and a non-square one are not, and the message names the field.
    for (side, ok) in [(256, true), (257, false)] {
        let app = win_app(&toml);
        write(app.input.path(), "assets/icon.png", &icon_png(side));
        let dir = app.w.release_dir("rel", &[]);
        let out = app.pack(&dir, "1.0.0", Some(&app.stub));
        if ok {
            assert_ok(&out, "a 256 px icon");
        } else {
            let err = assert_fails(&out, 1, "a 257 px icon");
            assert!(err.contains("install.icon"), "{err:?}");
        }
    }
    let app = win_app(&toml);
    let mut tall = icon_png(32);
    tall[20..24].copy_from_slice(&48u32.to_be_bytes());
    write(app.input.path(), "assets/icon.png", &tall);
    let dir = app.w.release_dir("rel", &[]);
    let err = assert_fails(&app.pack(&dir, "1.0.0", Some(&app.stub)), 1, "not square");
    assert!(
        err.contains("install.icon") && err.contains("not square"),
        "{err:?}"
    );

    // `[windows] icon` wins over `install.icon`, even over a PNG that would be refused.
    let ico = {
        let mut ico = vec![0, 0, 1, 0, 1, 0, 16, 16, 0, 0, 1, 0, 32, 0];
        ico.extend_from_slice(&4u32.to_le_bytes());
        ico.extend_from_slice(&22u32.to_le_bytes());
        ico.extend_from_slice(b"ICON");
        ico
    };
    let app = win_app(&toml);
    app.w.append_config("\n[windows]\nicon = \"app.ico\"\n");
    fs::write(app.w.dir.path().join("app.ico"), &ico).unwrap();
    write(app.input.path(), "assets/icon.png", &icon_png(999));
    let dir = app.w.release_dir("rel", &[]);
    assert_ok(&app.pack(&dir, "1.0.0", Some(&app.stub)), "an ico icon");
    assert!(icon_bytes(&app.stub_in(&dir, "1.0.0")).is_some());

    // A bad .ico names `[windows] icon`.
    for bad in [&b"not an icon"[..], &ico[..ico.len() - 1]] {
        let app = win_app(WIN_TOML);
        app.w.append_config("\n[windows]\nicon = \"app.ico\"\n");
        fs::write(app.w.dir.path().join("app.ico"), bad).unwrap();
        let dir = app.w.release_dir("rel", &[]);
        let err = assert_fails(&app.pack(&dir, "1.0.0", Some(&app.stub)), 1, "a bad ico");
        assert!(err.contains("[windows] icon"), "{err:?}");
    }
    // `[windows] icon` for a Linux target is not read.
    let w = World::new(1, 1);
    w.append_config(UPDATE_TOML);
    w.append_config("\n[windows]\nicon = \"missing.ico\"\n");
    let dir = w.release_dir("rel", &[]);
    let input = tempfile::tempdir().unwrap();
    app_tree(input.path(), "bin/app");
    let runtime = w.dir.path().join("runtime");
    fs::write(&runtime, runtime_elf(62, false)).unwrap();
    assert_ok(
        &pack_update(
            &w,
            input.path(),
            &dir,
            Some(&runtime),
            "1.0.0",
            "linux-x86_64",
        ),
        "a Linux pack ignores [windows]",
    );
}

/// The console variant for a terminal app (`install.terminal`), the GUI variant otherwise.
#[cfg(unix)]
#[test]
fn windows_stub_variant_follows_terminal() {
    let console = hardened_pe(0x8664, 3);
    let app = win_app(&format!("{WIN_TOML}terminal = true\n"));
    let console_path = app.w.dir.path().join("console.exe");
    fs::write(&console_path, &console).unwrap();
    let dir = app.w.release_dir("rel", &[]);
    let err = assert_fails(
        &app.pack(&dir, "1.0.0", Some(&app.stub)),
        1,
        "a GUI stub for a terminal app",
    );
    assert!(err.contains("--stub is not a console stub"), "{err:?}");
    assert!(err.contains("wrong Windows subsystem"), "{err:?}");
    assert_ok(
        &app.pack(&dir, "1.0.0", Some(&console_path)),
        "console stub",
    );
    let stamped = app.stub_in(&dir, "1.0.0");
    lunepack_core::check_pe_stub(&stamped, Target::WindowsX86_64, true).expect("a console stub");

    let app = win_app(WIN_TOML);
    let console_path = app.w.dir.path().join("console.exe");
    fs::write(&console_path, &console).unwrap();
    let dir = app.w.release_dir("rel", &[]);
    let err = assert_fails(
        &app.pack(&dir, "1.0.0", Some(&console_path)),
        1,
        "a console stub for a GUI app",
    );
    assert!(err.contains("--stub is not a GUI stub"), "{err:?}");
}

/// C2: the same inputs give identical stamped stubs, packs and manifests, and the stub's input
/// bytes reach the pack.
#[cfg(unix)]
#[test]
fn windows_pack_is_deterministic() {
    let toml = WIN_TOML.replace("assets/icon.svg", "assets/icon.png");
    let app = win_app(&toml);
    write(app.input.path(), "assets/icon.png", &icon_png(48));
    let (a, b) = (app.w.release_dir("a", &[]), app.w.release_dir("b", &[]));
    for dir in [&a, &b] {
        assert_ok(&app.pack(dir, "1.0.0", Some(&app.stub)), "pack");
    }
    for name in [
        "1.0.0/windows-x86_64.pack",
        "1.0.0/windows-x86_64.manifest.json",
    ] {
        assert_eq!(
            fs::read(a.join(name)).unwrap(),
            fs::read(b.join(name)).unwrap(),
            "{name}"
        );
    }
    assert_eq!(app.stub_in(&a, "1.0.0"), app.stub_in(&b, "1.0.0"));
    // A different stub gives a different pack.
    let other = app.w.dir.path().join("other.exe");
    let mut spec = exe_headers::PeSpec::hardened(2);
    spec.code_len = 0x800;
    fs::write(&other, exe_headers::pe_image(0x8664, &spec)).unwrap();
    let c = app.w.release_dir("c", &[]);
    assert_ok(&app.pack(&c, "1.0.0", Some(&other)), "pack");
    assert_ne!(
        fs::read(a.join("1.0.0/windows-x86_64.pack")).unwrap(),
        fs::read(c.join("1.0.0/windows-x86_64.pack")).unwrap()
    );
}

/// `--stub` refusals name the option or the field and never a value.
#[cfg(unix)]
#[test]
fn windows_stub_refusals() {
    let app = win_app(WIN_TOML);
    let dir = app.w.release_dir("rel", &[]);
    let fails = |out: Output, what: &str| assert_fails(&out, 1, what);

    let err = fails(app.pack(&dir, "1.0.0", None), "no --stub");
    assert!(err.contains("--stub is required"), "{err:?}");

    // Wrong machine, a C runtime import, no flags, no manifest, the wrong subsystem, not a PE.
    let mut crt = exe_headers::PeSpec::hardened(2);
    crt.imports.push("MSVCP140.dll".to_owned());
    let mut no_flags = exe_headers::PeSpec::hardened(2);
    no_flags.dependent_load_flags = None;
    let mut no_manifest = exe_headers::PeSpec::hardened(2);
    no_manifest.manifest = None;
    let cases: Vec<(&str, Vec<u8>, &str)> = vec![
        ("arm64", hardened_pe(0xAA64, 2), "another architecture"),
        ("crt", exe_headers::pe_image(0x8664, &crt), "C runtime"),
        (
            "flags",
            exe_headers::pe_image(0x8664, &no_flags),
            "DependentLoadFlags",
        ),
        (
            "manifest",
            exe_headers::pe_image(0x8664, &no_manifest),
            "manifest",
        ),
        ("console", hardened_pe(0x8664, 3), "subsystem"),
        ("bare", exe_headers::pe(0x8664, 4_096), "malformed"),
        ("elf", runtime_elf(62, false), "not an executable"),
    ];
    for (name, bytes, want) in cases {
        let path = app.w.dir.path().join(format!("{name}.exe"));
        fs::write(&path, bytes).unwrap();
        let err = fails(app.pack(&dir, "1.0.0", Some(&path)), name);
        assert!(err.contains("--stub is not a GUI stub"), "{name}: {err:?}");
        assert!(err.contains(want), "{name}: {err:?}");
        assert!(!err.contains(path.to_str().unwrap()), "{name}: {err:?}");
    }
    let missing = app.w.dir.path().join("missing.exe");
    fails(app.pack(&dir, "1.0.0", Some(&missing)), "a missing stub");

    // --stub for a Linux target, without --runtime, and without [update].
    let w = World::new(1, 1);
    w.append_config(UPDATE_TOML);
    let ldir = w.release_dir("rel", &[]);
    let linput = tempfile::tempdir().unwrap();
    app_tree(linput.path(), "bin/app");
    let runtime = w.dir.path().join("runtime");
    fs::write(&runtime, runtime_elf(62, false)).unwrap();
    let out = pack_win(
        &w,
        linput.path(),
        &ldir,
        Some(&runtime),
        Some(&app.stub),
        "1.0.0",
        "linux-x86_64",
    );
    let err = fails(out, "--stub for linux");
    assert!(err.contains("--stub is only for windows-*"), "{err:?}");
    let out = pack_win(
        &w,
        linput.path(),
        &ldir,
        None,
        Some(&app.stub),
        "1.0.0",
        "windows-x86_64",
    );
    let err = fails(out, "--stub without --runtime");
    assert!(err.contains("--stub needs --runtime"), "{err:?}");
    let w = World::new(1, 1);
    let ldir = w.release_dir("rel", &[]);
    let out = pack_win(
        &w,
        linput.path(),
        &ldir,
        None,
        Some(&app.stub),
        "1.0.0",
        "windows-x86_64",
    );
    let err = fails(out, "--stub without [update]");
    assert!(err.contains("--stub needs [update]"), "{err:?}");
}

/// The Windows rules on the config and the input: every clause of M7-D15's `name` rule, the `.exe`
/// entry, the numeric version, and the reserved stub name.
#[cfg(unix)]
#[test]
fn windows_pack_refusals_name_the_field_not_the_value() {
    let long = "N".repeat(65);
    let name_cases: [(&str, &str, &str); 5] = [
        (&long, "too long", "N"),
        ("Qa:zb", "a character Windows does not allow", "Qa:zb"),
        (" Qab", "starts with a dot or space", "Qab"),
        ("Qab.", "starts with a dot or space, or ends", "Qab"),
        ("Con.Qab", "a Windows device name", "Qab"),
    ];
    for (name, clause, secret) in name_cases {
        let app = win_app(&WIN_TOML.replace("name = \"Hello\"", &format!("name = \"{name}\"")));
        let dir = app.w.release_dir("rel", &[]);
        let err = assert_fails(&app.pack(&dir, "1.0.0", Some(&app.stub)), 1, clause);
        assert!(err.contains("[install] name"), "{clause}: {err:?}");
        assert!(err.contains(clause), "{clause}: {err:?}");
        if secret != "N" {
            assert!(!err.contains(secret), "{clause}: {err:?}");
        }
    }
    // The rule applies to Windows targets only: a Linux pack with the same names works.
    let w = World::new(1, 1);
    w.append_config(&UPDATE_TOML.replace("name = \"Hello\"", "name = \"Con: a/b.\""));
    let ldir = w.release_dir("rel", &[]);
    let linput = tempfile::tempdir().unwrap();
    app_tree(linput.path(), "bin/app");
    let runtime = w.dir.path().join("runtime");
    fs::write(&runtime, runtime_elf(62, false)).unwrap();
    assert_ok(
        &pack_update(
            &w,
            linput.path(),
            &ldir,
            Some(&runtime),
            "1.0.0",
            "linux-x86_64",
        ),
        "a Linux pack with a name Windows would refuse",
    );

    // The entry must be an .exe.
    let app = win_app(&WIN_TOML.replace("bin/app.exe", "bin/app"));
    write(app.input.path(), "bin/app", &exe_headers::pe(0x8664, 8_000));
    let dir = app.w.release_dir("rel", &[]);
    let err = assert_fails(
        &app.pack(&dir, "1.0.0", Some(&app.stub)),
        1,
        "entry not .exe",
    );
    assert!(err.contains("[install] entry"), "{err:?}");

    // The numeric version: each component at most 65535, the message names `--version`.
    let app = win_app(WIN_TOML);
    let dir = app.w.release_dir("rel", &[]);
    for version in ["65536.0.0", "1.65536.0", "1.0.65536"] {
        let err = assert_fails(&app.pack(&dir, version, Some(&app.stub)), 1, version);
        assert!(err.contains("--version"), "{version}: {err:?}");
        assert!(!err.contains("65536"), "{version}: {err:?}");
    }
    assert_ok(
        &app.pack(&dir, "65535.65535.65535", Some(&app.stub)),
        "the largest",
    );

    // The stub's name is reserved at any depth, ignoring case; the input is not touched.
    for at in ["bin/lunepack-stub.exe", "other/Lunepack-Stub.EXE"] {
        let app = win_app(WIN_TOML);
        write(app.input.path(), at, b"x");
        let dir = app.w.release_dir("rel", &[]);
        let err = assert_fails(&app.pack(&dir, "1.0.0", Some(&app.stub)), 1, at);
        assert!(err.contains("reserved"), "{at}: {err:?}");
    }
}
